        totalModalHpp,
        nilaiModalPengurangStok,
        hargaJualPerKg,
        totalNominal,
        labaKotor,
        divisi: finalDivisi,
        metodePembayaran: params.metodePembayaran,
        rekeningTujuan: finalRekeningTujuan,
        statusPembayaran,
        sisaPiutang,
        isNotaNgunci: false,
        isBelumPutusHargaJual: isBelumPutusHarga,
        selisihTimbangMuatKg,
        isHabisMuatSusut: isHabisMuatSusutFlag,
