        const jualSebelum = hbSales.filter((j) => isBeforeMonth(this.parseMonthYear(j.tanggal), m, targetTahun)).reduce((s, j) => s + (Number(j.beratBersih) || 0), 0);
        stokAwalKg += Math.max(0, awalManual + beliSebelum - jualSebelum);
